package game31

// ── P2P exchange: escrowed limit-order book (any coin pair) ──────────────────
//
// A maker escrows `give` and asks for `want` at their own price; takers fill
// at the maker's price (fully or partly). Cancel or expiry refunds the
// remaining escrow; the 2-grin posting fee is not refunded. No price bands.
//
// Storage (≈ 200 bytes per open order): no per-order tree node (one avl
// insert costs ~2.1 KB of storage deposit). Each maker has ONE compact string
// holding their ≤ 20 open orders, and each book side (want>give) is ONE
// fixed-width string of sorted 76-byte entries (priceKey24 + id12 + maker40),
// capped at maxSideOrders; when a side is full a new order must beat the
// worst one, which is then refunded to its maker (evicted).

import (
	"math/bits"
	"strconv"
	"strings"
	"time"

	"chain"
)

type order struct {
	id               uint64
	maker            string
	give, want       string
	remGive, remWant uint64
	expiry           int64
	pk               string // price key part of the book key
}

func padU(n uint64, w int) string {
	s := strconv.FormatUint(n, 10)
	for len(s) < w {
		s = "0" + s
	}
	return s
}

const hexDigits = "0123456789abcdef"

// priceKey = want-per-give × 1e12 as a fixed-width 24-hex-digit number
// (96 bits; amounts ≤ 1e15 keep it < 2^90). Lexicographic = numeric order,
// so ascending book keys are the cheapest asks first for takers.
func priceKey(wantAmt, giveAmt uint64) string {
	hi, lo := bits.Mul64(wantAmt, 1000000000000)
	qhi := hi / giveAmt
	qlo, _ := bits.Div64(hi%giveAmt, lo, giveAmt)
	if qhi >= 1<<32 {
		panic("price out of range")
	}
	b := make([]byte, 24)
	for i := 7; i >= 0; i-- {
		b[i] = hexDigits[qhi&15]
		qhi >>= 4
	}
	for i := 23; i >= 8; i-- {
		b[i] = hexDigits[qlo&15]
		qlo >>= 4
	}
	return string(b)
}

const (
	sideEntryLen  = 76  // priceKey(24) + id(12) + maker address(40)
	sideSortLen   = 36  // entries sort by priceKey then id (FIFO within a price)
	maxSideOrders = 256 // open orders per book side; bounds every string we rewrite
)

// maker record: id12|give|want|remGive|remWant|expiry|pk
func encodeOrder(o *order) string {
	return padU(o.id, 12) + "|" + o.give + "|" + o.want + "|" + u(o.remGive) + "|" + u(o.remWant) + "|" +
		strconv.FormatInt(o.expiry, 10) + "|" + o.pk
}

func decodeOrder(maker, rec string) *order {
	f := strings.Split(rec, "|")
	if len(f) != 7 {
		panic("corrupt order")
	}
	id, _ := strconv.ParseUint(f[0], 10, 64)
	rg, _ := strconv.ParseUint(f[3], 10, 64)
	rw, _ := strconv.ParseUint(f[4], 10, 64)
	ex, _ := strconv.ParseInt(f[5], 10, 64)
	return &order{id: id, maker: maker, give: f[1], want: f[2], remGive: rg, remWant: rw, expiry: ex, pk: f[6]}
}

func makerRecs(maker string) []string {
	if !makerBooks.Has(maker) {
		return nil
	}
	v := makerBooks.Get(maker).(string)
	if v == "" {
		return nil
	}
	return strings.Split(v, ";")
}

func setMakerRecs(maker string, recs []string) {
	if len(recs) == 0 {
		makerBooks.Remove(maker)
		return
	}
	makerBooks.Set(maker, strings.Join(recs, ";"))
}

// loadOrderOf finds one of maker's open orders (≤ 20 records scanned).
func loadOrderOf(maker string, id uint64) *order {
	pre := padU(id, 12) + "|"
	for _, r := range makerRecs(maker) {
		if strings.HasPrefix(r, pre) {
			return decodeOrder(maker, r)
		}
	}
	return nil
}

func saveOrder(o *order) {
	recs := makerRecs(o.maker)
	pre := padU(o.id, 12) + "|"
	for i, r := range recs {
		if strings.HasPrefix(r, pre) {
			recs[i] = encodeOrder(o)
			setMakerRecs(o.maker, recs)
			return
		}
	}
	panic("invariant: order not found")
}

func sideKey(want, give string) string { return want + ">" + give }

func sideEntry(o *order) string { return o.pk + padU(o.id, 12) + o.maker }

func sideStr(k string) string {
	if !sides.Has(k) {
		return ""
	}
	return sides.Get(k).(string)
}

// sideSearch returns the index of the first entry whose sort key is ≥ key.
func sideSearch(s, key string) int {
	lo, hi := 0, len(s)/sideEntryLen
	for lo < hi {
		mid := (lo + hi) / 2
		if s[mid*sideEntryLen:mid*sideEntryLen+sideSortLen] < key {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

func sideInsert(o *order) {
	k := sideKey(o.want, o.give)
	s := sideStr(k)
	e := sideEntry(o)
	i := sideSearch(s, e[:sideSortLen]) * sideEntryLen
	sides.Set(k, s[:i]+e+s[i:])
}

func sideRemove(o *order) {
	k := sideKey(o.want, o.give)
	s := sideStr(k)
	e := sideEntry(o)
	i := sideSearch(s, e[:sideSortLen]) * sideEntryLen
	if i+sideEntryLen > len(s) || s[i:i+sideEntryLen] != e {
		panic("invariant: book entry missing")
	}
	s = s[:i] + s[i+sideEntryLen:]
	if s == "" {
		sides.Remove(k)
	} else {
		sides.Set(k, s)
	}
}

// iterSide walks a taker's side (pays `pay`, gets `get`) best price first.
func iterSide(pay, get string, fn func(maker string, id uint64) bool) {
	s := sideStr(sideKey(pay, get))
	for i := 0; i+sideEntryLen <= len(s); i += sideEntryLen {
		e := s[i : i+sideEntryLen]
		id, _ := strconv.ParseUint(e[24:36], 10, 64)
		if fn(e[36:], id) {
			return
		}
	}
}

func sideCount(pay, get string) int { return len(sideStr(sideKey(pay, get))) / sideEntryLen }

// grinValueMilli = amt × reference value (milli-grin), saturating at 2^64-1.
func grinValueMilli(coin string, amt uint64) uint64 {
	hi, lo := bits.Mul64(amt, prefMilli[requireCoin(coin)])
	if hi != 0 {
		return ^uint64(0)
	}
	return lo
}

func openOrderCount(maker string) uint64 { return uint64(len(makerRecs(maker))) }

// PlaceOrder escrows giveAmt of `give` and lists it for wantAmt of `want`
// (any pair). No upfront posting fee — the 0.90% maker fee is deducted
// from the maker's proceeds at fill time. Returns the order id.
// expirySecs 0 = 72 h; max 7 days.
func PlaceOrder(cur realm, give string, giveAmt uint64, want string, wantAmt uint64, expirySecs int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireCoin(give)
	requireCoin(want)
	if give == want {
		panic("give and want must differ")
	}
	requireAmount("giveAmt", giveAmt)
	requireAmount("wantAmt", wantAmt)
	if grinValueMilli(give, giveAmt) < minOrderGrinX1k {
		panic("order too small: minimum is 50 grin of value")
	}
	if expirySecs == 0 {
		expirySecs = defaultExpiry
	}
	if expirySecs < 60 || expirySecs > maxExpiry {
		panic("expiry must be between 60 s and 7 days")
	}
	if openOrderCount(caller) >= maxOpenOrders {
		panic("max 20 open orders")
	}
	if len(caller) != 40 {
		panic("invalid maker address")
	}
	pk := priceKey(wantAmt, giveAmt)
	nextId := addChk(nextOrderId, 1)
	// A full side only takes an order that beats its worst one (which is then
	// refunded to its maker): spam can't lock the book with absurd prices.
	var evict *order
	if sideCount(want, give) >= maxSideOrders {
		s := sideStr(sideKey(want, give))
		w := s[len(s)-sideEntryLen:]
		if pk+padU(nextId, 12) >= w[:sideSortLen] {
			panic("book side full: price must beat the worst open order")
		}
		wid, _ := strconv.ParseUint(w[24:36], 10, 64)
		evict = loadOrderOf(w[36:], wid)
		if evict == nil {
			panic("invariant: book entry without order")
		}
	}
	requireBalance(caller, give, giveAmt)
	// ── all checks passed; writes start here ──
	debitBal(caller, give, giveAmt) // escrow

	if evict != nil {
		closeOrder(evict, "evicted")
	}
	nextOrderId = nextId
	o := &order{id: nextId, maker: caller, give: give, want: want, remGive: giveAmt, remWant: wantAmt,
		expiry: time.Now().Unix() + expirySecs, pk: pk}
	setMakerRecs(caller, append(makerRecs(caller), encodeOrder(o)))
	sideInsert(o)
	openOrderTotal = addChk(openOrderTotal, 1)
	chain.Emit("OrderPlaced", "id", u(o.id), "maker", caller, "give", give, "giveAmt", u(giveAmt),
		"want", want, "wantAmt", u(wantAmt), "expiry", strconv.FormatInt(o.expiry, 10))
	return o.id
}

// closeOrder refunds the remaining escrow to the MAKER (never anyone else)
// and deletes the order. Every close path goes through here.
func closeOrder(o *order, reason string) {
	refund := o.remGive
	if refund > 0 {
		creditBal(o.maker, o.give, refund)
		o.remGive = 0
	}
	sideRemove(o)
	recs := makerRecs(o.maker)
	pre := padU(o.id, 12) + "|"
	for i, r := range recs {
		if strings.HasPrefix(r, pre) {
			recs = append(recs[:i], recs[i+1:]...)
			break
		}
	}
	setMakerRecs(o.maker, recs)
	openOrderTotal = subChk(openOrderTotal, 1)
	chain.Emit("OrderClosed", "id", u(o.id), "maker", o.maker, "reason", reason, "refund", u(refund))
}

// CancelOrder: the maker gets the remaining escrow back. Works while paused
// and for banned makers; only the maker can cancel.
func CancelOrder(cur realm, id uint64) {
	caller := exchangeCaller(cur)
	// Lookup is by the caller's own orders only: nobody can name someone
	// else's order here.
	o := loadOrderOf(caller, id)
	if o == nil {
		panic("no such open order (or not your order)")
	}
	closeOrder(o, "cancel")
}

// SweepExpiredOrders closes up to maxScanPerTx expired orders of one book
// side, refunding each maker. Anyone may call it (also while paused).
func SweepExpiredOrders(cur realm, pay string, get string) int {
	exchangeCaller(cur)
	now := time.Now().Unix()
	var expired []*order
	scanned := 0
	iterSide(pay, get, func(maker string, id uint64) bool {
		scanned++
		if scanned > maxScanPerTx {
			return true
		}
		o := loadOrderOf(maker, id)
		if o != nil && o.expiry < now {
			expired = append(expired, o)
		}
		return false
	})
	for _, o := range expired {
		closeOrder(o, "expired")
	}
	return len(expired)
}

type fillStep struct {
	o    *order
	x, g uint64 // taker pays x (+fee) of `pay`, receives g of `get`
}

// planFills walks the book for a taker (read-only). budget is the most the
// taker will spend INCLUDING the taker fee. Own orders are skipped (no
// self-match); expired orders are returned for closing.
func planFills(caller, pay, get string, budget uint64, maxFills int, now int64) ([]fillStep, []*order, uint64, uint64) {
	if maxFills <= 0 || maxFills > maxFillsPerTx {
		maxFills = maxFillsPerTx
	}
	var steps []fillStep
	var expired []*order
	remaining := budget
	spent, got := uint64(0), uint64(0)
	scanned := 0
	iterSide(pay, get, func(maker string, id uint64) bool {
		scanned++
		if scanned > maxScanPerTx || len(steps) >= maxFills || remaining == 0 {
			return true
		}
		o := loadOrderOf(maker, id)
		if o == nil {
			return false
		}
		if o.expiry < now {
			expired = append(expired, o)
			return false
		}
		if o.maker == caller {
			return false // no self-match: skip, never touch the taker's own order
		}
		// largest x with x + ceil(x × takerFee) ≤ remaining
		x := mulDiv(remaining, 10000, 10000+takerFeeBps)
		for i := 0; i < 4 && x > 0 && addChk(x, mulDivUp(x, takerFeeBps, 10000)) > remaining; i++ {
			x--
		}
		if x > o.remWant {
			x = o.remWant
		}
		if x == 0 {
			return true
		}
		g := o.remGive
		if x < o.remWant {
			g = mulDiv(x, o.remGive, o.remWant) // floor: the maker never sells below their price
		}
		if g == 0 {
			return true
		}
		cost := addChk(x, mulDivUp(x, takerFeeBps, 10000))
		steps = append(steps, fillStep{o: o, x: x, g: g})
		remaining = subChk(remaining, cost)
		spent = addChk(spent, cost)
		got = addChk(got, g)
		return false
	})
	return steps, expired, spent, got
}

// executeFills applies a plan: the taker pays each maker x (plus taker fee),
// receives g from escrow. The maker receives x minus the 0.90% maker fee
// (deducted from proceeds, not from escrow). Returns total received by taker.
func executeFills(caller, pay string, steps []fillStep) uint64 {
	got := uint64(0)
	for _, st := range steps {
		o := st.o
		takerFee := mulDivUp(st.x, takerFeeBps, 10000)
		makerFee := mulDivUp(st.x, makerFeeBps, 10000)
		// Taker pays x + takerFee; maker receives x - makerFee
		debitBal(caller, pay, addChk(st.x, takerFee))
		accrueProtocolFee(pay, addChk(takerFee, makerFee))
		creditBal(o.maker, pay, subChk(st.x, makerFee))
		o.remWant = subChk(o.remWant, st.x)
		o.remGive = subChk(o.remGive, st.g)
		got = addChk(got, st.g)
		chain.Emit("OrderFilled", "id", u(o.id), "maker", o.maker, "taker", caller,
			"paid", u(st.x), "takerFee", u(takerFee), "makerFee", u(makerFee), "got", u(st.g))
		if o.remWant == 0 || o.remGive == 0 {
			closeOrder(o, "filled")
		} else if grinValueMilli(o.give, o.remGive) < minOrderGrinX1k {
			closeOrder(o, "dust")
		} else {
			saveOrder(o)
		}
	}
	return got
}

// FillOrders: spend at most payAmt of `pay` (taker fee included) on the
// best-priced orders that give `get`; receive at least minGet or revert.
// ≤ 10 fills and ≤ 20 scanned entries per call.
func FillOrders(cur realm, pay string, get string, payAmt uint64, minGet uint64, maxFills int, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireCoin(pay)
	requireCoin(get)
	requireAmount("payAmt", payAmt)
	steps, expired, spent, planned := planFills(caller, pay, get, payAmt, maxFills, time.Now().Unix())
	if planned == 0 || planned < minGet {
		panic("slippage: received below minimum")
	}
	requireBalance(caller, pay, spent)
	// ── all checks passed; writes start here ──
	for _, o := range expired {
		closeOrder(o, "expired")
	}
	got := executeFills(caller, pay, steps)
	if got != planned {
		panic("invariant: fill plan mismatch")
	}
	creditBal(caller, get, got)
	return got
}

// ── views ────────────────────────────────────────────────────────────────────

func orderJSON(o *order) string {
	return `{"id":"` + u(o.id) + `","maker":"` + o.maker + `","give":` + jsonStr(o.give) + `,"want":` + jsonStr(o.want) +
		`,"remGive":"` + u(o.remGive) + `","remWant":"` + u(o.remWant) + `","expiry":` + strconv.FormatInt(o.expiry, 10) + `}`
}

// Order shows one open order of `maker` (lookups are per maker by design).
func Order(maker string, id uint64) string {
	o := loadOrderOf(maker, id)
	if o == nil {
		return `{"id":"` + u(id) + `","open":false}`
	}
	return orderJSON(o)
}

// OrdersOf lists an address's open orders (≤ 20 by construction).
func OrdersOf(addr string) string {
	out := "["
	for i, r := range makerRecs(addr) {
		if i > 0 {
			out += ","
		}
		out += orderJSON(decodeOrder(addr, r))
	}
	return out + "]"
}

// BookDepth lists asks for a taker who pays `pay` and gets `get`, best price
// first (≤ 50 rows; offset < maxSideOrders).
func BookDepth(pay string, get string, limit int, offset int) string {
	if limit <= 0 || limit > maxViewLimit {
		limit = maxViewLimit
	}
	if offset < 0 || offset >= maxSideOrders {
		offset = 0
	}
	out := "["
	i, n := 0, 0
	iterSide(pay, get, func(maker string, id uint64) bool {
		if i < offset {
			i++
			return false
		}
		if o := loadOrderOf(maker, id); o != nil {
			if n > 0 {
				out += ","
			}
			out += orderJSON(o)
			n++
		}
		return n >= limit
	})
	return out + "]"
}

// QuoteFill previews FillOrders for a budget (fee included): {"spent","got"}.
func QuoteFill(caller string, pay string, get string, payAmt uint64, maxFills int) string {
	if payAmt == 0 || payAmt > maxAmount {
		return `{"spent":"0","got":"0","fills":0}`
	}
	steps, _, spent, got := planFills(caller, pay, get, payAmt, maxFills, time.Now().Unix())
	return `{"spent":"` + u(spent) + `","got":"` + u(got) + `","fills":` + strconv.Itoa(len(steps)) + `}`
}

package game31

// ── P2P exchange: core (docs/P2P_EXCHANGE_PLAN.md, docs/EXCHANGE_SECURITY_REVIEW.md)
//
// Open economy (Simion, 2026-10-11): no price-impact cap, no price bands, no
// reference-price checks on deposits. Every value-moving call takes the
// trader's own protection instead: a minimum output (minOut / minShares /
// minGet) and a deadline.
//
// Security rules this file enforces for the whole exchange:
//   - The exchange only moves coins that already exist in `balances`
//     (debitBal → reserves/escrow → creditBal). It never mints.
//   - The admin has NO path to pool reserves, LP positions, escrowed orders,
//     accrued casino fees or player balances. Admin powers are listed in
//     docs/EXCHANGE_SECURITY_REVIEW.md §2.
//   - Pause stops only NEW swaps / orders / deposits. Exits — RemoveLiquidity,
//     CancelOrder, SweepExpiredOrders, WithdrawProtocolFees — always work,
//     also while paused and for banned addresses.
//   - All amounts are uint64; every add/mul is checked (panics, never wraps);
//     products use 128-bit intermediates; rounding favors the pool / maker.
//   - No exchange path calls another realm or sends coins: no reentrancy.
//   - Loops are bounded by constants (≤ maxFillsPerTx fills, ≤ maxScanPerTx
//     scanned entries, ≤ maxViewLimit view rows, ≤ maxOpenOrders per maker).
//   - Block time is used only for deadlines, order expiry and the LP warm-up.

import (
	"math/bits"
	"strconv"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
)

const (
	hubCoin = "grin"

	// Pools: 0.50% of the input; 0.35% stays in the pool (LPs), 0.15% is the
	// protocol fee, split 50/50 between the admin and the casino pool.
	poolFeeBps  = uint64(50)
	protoFeeBps = uint64(15)

	minLiquidity     = uint64(1000) // first-deposit shares burned forever
	minOpenDepthGrin = uint64(2000) // a pool takes swaps only once rGrin ≥ this
	warmupSecs       = int64(600)   // LP fee warm-up (principal always instant)
	rootKScale       = uint64(1000000000)

	// Order book: takers 0.50% of what they pay; makers 0.90% of what they
	// receive (deducted from the maker's proceeds at fill time, never upfront).
	// No flat posting fee — any amount meeting the size floor can be listed.
	takerFeeBps     = uint64(50)
	makerFeeBps     = uint64(90)
	minOrderGrinX1k = uint64(50000) // 50 grin of value (reference table) — size floor only
	maxOpenOrders   = uint64(20)
	defaultExpiry   = int64(72 * 3600)
	maxExpiry       = int64(7 * 24 * 3600)
	maxFillsPerTx   = 10
	maxScanPerTx    = 20
	maxViewLimit    = 50

	// Upper bound for any single amount argument. Keeps every intermediate far
	// from uint64 limits (balances are uint64 too) and rejects absurd inputs.
	maxAmount = uint64(1000000000000000) // 1e15

)

// Reference value per rarity in milli-grin (RARITY_VALUE ×1000). Used ONLY
// for the 50-grin minimum order size — never for prices.
var prefMilli = [7]uint64{1000, 3200, 11000, 40000, 160000, 720000, 3600000}

var (
	pools       avl.Tree // coin → *pool
	lpPositions avl.Tree // coin+":"+addr → *lpPos
	adminFees   avl.Tree // coin → admin's accrued protocol fees (pull)
	casinoPool  avl.Tree // coin → casino pool balance (fees in, capped jackpots out)
	makerBooks     avl.Tree // maker → ";"-joined compact order records (≤ maxOpenOrders)
	sides          avl.Tree // want+">"+give → sorted fixed-width entries (≤ maxSideOrders)
	openOrderTotal uint64
	nextOrderId    uint64
	exPaused    bool

	// Lifetime accounting (Render + audits).
	adminFeesWithdrawn avl.Tree // coin → lifetime withdrawn by the admin
	adminGnotWithdrawn int64    // ugnot withdrawn by WithdrawFunds (≤ passRevenueUgnot)
)

// ── checked math ─────────────────────────────────────────────────────────────

func addChk(a, b uint64) uint64 {
	s, carry := bits.Add64(a, b, 0)
	if carry != 0 {
		panic("math overflow")
	}
	return s
}

func subChk(a, b uint64) uint64 {
	if b > a {
		panic("math underflow")
	}
	return a - b
}

// mulDiv = floor(a*b/c) with a 128-bit product; panics if c == 0 or the
// quotient does not fit in 64 bits.
func mulDiv(a, b, c uint64) uint64 {
	if c == 0 {
		panic("division by zero")
	}
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("math overflow")
	}
	q, _ := bits.Div64(hi, lo, c)
	return q
}

// mulDivUp = ceil(a*b/c).
func mulDivUp(a, b, c uint64) uint64 {
	if c == 0 {
		panic("division by zero")
	}
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("math overflow")
	}
	q, r := bits.Div64(hi, lo, c)
	if r > 0 {
		q = addChk(q, 1)
	}
	return q
}

// isqrt128 = floor(sqrt(a*b)) for the 128-bit product (Newton, bounded).
func isqrt128(a, b uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if hi == 0 {
		return isqrt(lo)
	}
	// sqrt of a 128-bit number < 2^64. Start above the root and descend.
	x := ^uint64(0)
	for i := 0; i < 200; i++ {
		if hi >= x { // product/x overflows ⇒ x below the root; cannot happen when descending from max
			panic("isqrt: bad state")
		}
		q, _ := bits.Div64(hi, lo, x)
		nx := (x >> 1) + (q >> 1) + (x & q & 1)
		if nx >= x {
			return x
		}
		x = nx
	}
	panic("isqrt: no convergence")
}

func isqrt(n uint64) uint64 {
	if n < 2 {
		return n
	}
	x := n
	y := x/2 + 1
	for i := 0; i < 200 && y < x; i++ {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// mulLess reports a*b < c*d using 128-bit products.
func mulLess(a, b, c, d uint64) bool {
	h1, l1 := bits.Mul64(a, b)
	h2, l2 := bits.Mul64(c, d)
	return h1 < h2 || (h1 == h2 && l1 < l2)
}

// requireBalance checks a balance before any write, so a failing call
// changes nothing (validate-then-write).
func requireBalance(addr, coin string, amt uint64) {
	if have := balOf(addr, coin); have < amt {
		panic("insufficient " + coin + ": need " + u(amt) + " have " + u(have))
	}
}

func requireAmount(name string, v uint64) {
	if v == 0 || v > maxAmount {
		panic(name + " must be between 1 and " + strconv.FormatUint(maxAmount, 10))
	}
}

func u(n uint64) string { return strconv.FormatUint(n, 10) }

// ── gates ────────────────────────────────────────────────────────────────────

// exchangeCaller returns the caller for exchange writes. Only end users (an
// EOA MsgCall or the user's own MsgRun) may trade: other realms can't act
// through the exchange, so there is no cross-realm call surface at all.
func exchangeCaller(cur realm) string {
	prev := cur.Previous()
	if prev.PkgPath() != "" {
		panic("exchange calls must come directly from a user")
	}
	return prev.Address().String()
}

// requireMarketOpen gates NEW activity (swaps, deposits, orders, fills).
// Trading opens only after FinalizeMigration: MigrateBatch SETs balances, so
// trading before that could duplicate or lose escrowed coins.
func requireMarketOpen(caller string) {
	if !migrationFinalized {
		panic("exchange opens after FinalizeMigration")
	}
	if exPaused {
		panic("exchange paused: new trades are off; unstake and cancel still work")
	}
	if isBlacklisted(caller) {
		panic("address banned")
	}
}

func requireDeadline(deadline int64) {
	if deadline <= 0 {
		panic("deadline required (unix seconds)")
	}
	if time.Now().Unix() > deadline {
		panic("deadline passed")
	}
}

func requireCoin(coin string) int {
	r, ok := coinRarity[coin]
	if !ok {
		panic("unknown coin id: " + coin)
	}
	return r
}

// Trading is open to every account (Simion, 2026-10-11): no tool requirement
// to swap, post, fill or stake. Anti-spam comes from the 50-grin order
// minimum, the 2-grin post fee, the 0.5% taker/pool fees, the 20-open-orders
// limit per maker and the 2,000-grin minimum pool depth.

// No receive cap (Simion, 2026-10-11): every coin is freely transferable and
// tradable, whatever tools the receiver owns.

// ── protocol fees ────────────────────────────────────────────────────────────

// accrueProtocolFee splits amt of coin 50/50: the floor half to the admin's
// fee ledger, the rest to the casino pool. Both stay inside the realm.
func accrueProtocolFee(coin string, amt uint64) {
	if amt == 0 {
		return
	}
	half := amt / 2
	if half > 0 {
		setU(&adminFees, coin, addChk(getU(&adminFees, coin), half))
	}
	setU(&casinoPool, coin, addChk(getU(&casinoPool, coin), amt-half))
	casStat(coin, "", "fees", amt-half)
	chain.Emit("ProtocolFeesAccrued", "coin", coin, "admin", u(half), "casino", u(amt-half))
}

// WithdrawProtocolFees moves the admin's OWN accrued fees for `coin` into the
// admin's balance. It reads only adminFees (never reserves, escrow, the
// casino pool or anyone's balance) and works while paused.
func WithdrawProtocolFees(cur realm, coin string) uint64 {
	requireAdmin(cur)
	requireCoin(coin)
	amt := getU(&adminFees, coin)
	if amt == 0 {
		panic("no fees to withdraw for " + coin)
	}
	adminFees.Remove(coin)
	setU(&adminFeesWithdrawn, coin, addChk(getU(&adminFeesWithdrawn, coin), amt))
	to := admin.String()
	creditBal(to, coin, amt)
	chain.Emit("ProtocolFeesWithdrawn", "coin", coin, "to", to, "amount", u(amt))
	return amt
}

// ── casino pool (fee share + losing stakes in, wins out; never minted) ─────
//
// casinoPool[coin]     total pool, including the reserved part
// casinoReserved[coin] sum of potential net payouts of unsettled bets
// casinoDay[coin]      "day:snapshot:paid:received" for the current UTC day
//
// A bet is accepted only if the pool can pay it in full: its potential net
// payout (= the stake, since a win pays 2×) is reserved at placement, so a
// reveal never pays partially and the pool can't go below zero.









// ── admin controls (launch only; none touch user funds) ──────────────────────

// SetExchangePaused stops NEW swaps, deposits, orders and fills. It can't
// stop RemoveLiquidity, CancelOrder, SweepExpiredOrders or fee withdrawals.
func SetExchangePaused(cur realm, p bool) {
	requireAdmin(cur)
	exPaused = p
	chain.Emit("ExchangePaused", "paused", strconv.FormatBool(p))
}

func ExchangeStatus() string {
	return `{"open":` + strconv.FormatBool(migrationFinalized && !exPaused) +
		`,"paused":` + strconv.FormatBool(exPaused) +
		`,"finalized":` + strconv.FormatBool(migrationFinalized) +
		`,"pools":` + strconv.Itoa(pools.Size()) +
		`,"openOrders":` + strconv.FormatUint(openOrderTotal, 10) +
		`,"nextOrderId":"` + u(nextOrderId) + `"` +
		`,"poolFeeBps":` + u(poolFeeBps) + `,"protoFeeBps":` + u(protoFeeBps) +
		`,"takerFeeBps":` + u(takerFeeBps) + `,"makerFeeBps":` + u(makerFeeBps) +
		`,"postFeeGrin":0` +
		`,"minOpenDepthGrin":` + u(minOpenDepthGrin) + `,"warmupSecs":` + strconv.FormatInt(warmupSecs, 10) + `}`
}

func ProtocolFees(coin string) string {
	return `{"coin":` + jsonStr(coin) + `,"admin":"` + u(getU(&adminFees, coin)) +
		`","adminWithdrawn":"` + u(getU(&adminFeesWithdrawn, coin)) +
		`","casino":"` + u(getU(&casinoPool, coin)) + `"}`
}

package game31

// ── P2P exchange: COIN/GRIN constant-product pools ───────────────────────────
//
// Reserves are internal counters, never "the realm's balance": a Transfer or
// bank send to the realm address can't move them (no donation attack).
// Rounding: swap fee up, output down, minted shares down, withdrawals down —
// always in the pool's favor. k (and √k per share) never decreases on a swap.

import (
	"strconv"
	"time"

	"chain"
)

type pool struct {
	coin        string
	rCoin, rHub uint64 // reserves (coin side, grin side)
	shares      uint64 // total shares, including the burned minLiquidity
	paused      bool   // per-pool: stops new swaps/deposits only
}

type lpPos struct {
	shares    uint64
	entryRKPS uint64 // √k per share × rootKScale at (share-weighted) entry
	depositTs int64  // share-weighted deposit time (warm-up clock)
}

func getPool(coin string) *pool {
	if !pools.Has(coin) {
		panic("no pool for " + coin)
	}
	return pools.Get(coin).(*pool)
}

func rootKPerShare(p *pool) uint64 {
	if p.shares == 0 {
		return 0
	}
	return mulDiv(isqrt128(p.rCoin, p.rHub), rootKScale, p.shares)
}

// CreatePool opens an empty COIN/GRIN pool (admin, per the launch schedule).
// It holds nothing until players deposit; the admin can't deposit for anyone,
// withdraw from it or close it.
func CreatePool(cur realm, coin string) {
	requireAdmin(cur)
	if coin == hubCoin {
		panic("grin is the hub coin: pools are COIN/GRIN")
	}
	requireCoin(coin)
	if pools.Has(coin) {
		panic("pool exists")
	}
	pools.Set(coin, &pool{coin: coin})
	chain.Emit("PoolCreated", "coin", coin)
}

// OpenPool creates a new COIN/GRIN pool and immediately deposits the first
// liquidity, atomically setting the opening price. Any player who holds the
// coin and enough Grin can call this — no admin required.
//
// coinAmt and grinAmt set the price ratio; whoever calls this first for a coin
// controls the opening price, so choose amounts that reflect the coin's real
// value. 1,000 shares are permanently burned as a sandwich-resistance seed.
// Returns the number of LP shares minted for the caller.
func OpenPool(cur realm, coin string, coinAmt uint64, grinAmt uint64, minShares uint64, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("coinAmt", coinAmt)
	requireAmount("grinAmt", grinAmt)
	if coin == hubCoin {
		panic("grin is the hub coin: pools are COIN/GRIN")
	}
	requireCoin(coin)
	if pools.Has(coin) {
		panic("pool already exists: use AddLiquidity to stake")
	}
	// First-deposit size check: sqrt(coinAmt*grinAmt) must exceed minLiquidity.
	s := isqrt128(coinAmt, grinAmt)
	if s <= minLiquidity {
		panic("first deposit too small: sqrt(coinAmt x grinAmt) must exceed 1000")
	}
	minted := s - minLiquidity
	if minted < minShares {
		panic("slippage: shares below minimum")
	}
	requireBalance(caller, coin, coinAmt)
	requireBalance(caller, hubCoin, grinAmt)
	// ── all checks passed; writes start here ──
	pools.Set(coin, &pool{coin: coin})
	chain.Emit("PoolCreated", "coin", coin)
	p := getPool(coin)
	p.shares = addChk(minted, minLiquidity) // minLiquidity shares burned forever
	debitBal(caller, coin, coinAmt)
	debitBal(caller, hubCoin, grinAmt)
	p.rCoin = coinAmt
	p.rHub = grinAmt
	now := time.Now().Unix()
	rk := rootKPerShare(p)
	lpPositions.Set(coin+":"+caller, &lpPos{shares: minted, entryRKPS: rk, depositTs: now})
	chain.Emit("LiquidityAdded", "coin", coin, "who", caller,
		"coinIn", u(coinAmt), "grinIn", u(grinAmt), "shares", u(minted))
	return minted
}

// SetPoolPaused stops new swaps and deposits on one pool. Withdrawals stay open.
func SetPoolPaused(cur realm, coin string, p bool) {
	requireAdmin(cur)
	getPool(coin).paused = p
	chain.Emit("PoolPaused", "coin", coin, "paused", strconv.FormatBool(p))
}

// AddLiquidity deposits up to coinMax of `coin` and grinMax grin. The first
// deposit sets the price (open economy: any ratio) and burns minLiquidity
// shares; later deposits take the current ratio (never more than either cap).
// Reverts unless at least minShares are minted.
func AddLiquidity(cur realm, coin string, coinMax uint64, grinMax uint64, minShares uint64, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("coinMax", coinMax)
	requireAmount("grinMax", grinMax)
	p := getPool(coin)
	if p.paused {
		panic("pool paused")
	}
	var aCoin, aHub, minted uint64
	if p.shares == 0 {
		aCoin, aHub = coinMax, grinMax
		s := isqrt128(aCoin, aHub)
		if s <= minLiquidity {
			panic("first deposit too small: sqrt(coin×grin) must exceed 1000")
		}
		minted = s - minLiquidity
	} else {
		aHub = grinMax
		aCoin = mulDivUp(aHub, p.rCoin, p.rHub)
		if aCoin > coinMax {
			aCoin = coinMax
			aHub = mulDivUp(aCoin, p.rHub, p.rCoin)
		}
		s1 := mulDiv(aCoin, p.shares, p.rCoin)
		s2 := mulDiv(aHub, p.shares, p.rHub)
		minted = s1
		if s2 < minted {
			minted = s2
		}
		if minted == 0 {
			panic("deposit too small for one share")
		}
	}
	if minted < minShares {
		panic("slippage: shares below minimum")
	}
	requireBalance(caller, coin, aCoin)
	requireBalance(caller, hubCoin, aHub)
	// ── all checks passed; writes start here ──
	if p.shares == 0 {
		p.shares = addChk(minted, minLiquidity) // minLiquidity shares belong to nobody (burned)
	} else {
		p.shares = addChk(p.shares, minted)
	}
	debitBal(caller, coin, aCoin)
	debitBal(caller, hubCoin, aHub)
	p.rCoin = addChk(p.rCoin, aCoin)
	p.rHub = addChk(p.rHub, aHub)

	key := coin + ":" + caller
	now := time.Now().Unix()
	rk := rootKPerShare(p)
	if lpPositions.Has(key) {
		pos := lpPositions.Get(key).(*lpPos)
		tot := addChk(pos.shares, minted)
		pos.entryRKPS = addChk(mulDiv(pos.entryRKPS, pos.shares, tot), mulDivUp(rk, minted, tot))
		// share-weighted deposit time: a top-up restarts the warm-up in proportion.
		pos.depositTs = int64(addChk(mulDiv(uint64(pos.depositTs), pos.shares, tot), mulDivUp(uint64(now), minted, tot)))
		pos.shares = tot
	} else {
		lpPositions.Set(key, &lpPos{shares: minted, entryRKPS: rk, depositTs: now})
	}
	chain.Emit("LiquidityAdded", "coin", coin, "who", caller,
		"coinIn", u(aCoin), "grinIn", u(aHub), "shares", u(minted))
	return minted
}

// lpPayout computes what `shares` of a position withdraw right now:
// pro-rata of CURRENT reserves (floor). Within the warm-up the fee growth
// since entry (√k/share above entry) stays in the pool for the other LPs;
// principal is never cut below its entry-value share.
func lpPayout(p *pool, pos *lpPos, shares uint64, now int64) (uint64, uint64) {
	outCoin := mulDiv(shares, p.rCoin, p.shares)
	outHub := mulDiv(shares, p.rHub, p.shares)
	if now-pos.depositTs < warmupSecs {
		rk := rootKPerShare(p)
		if rk > pos.entryRKPS {
			outCoin = mulDiv(outCoin, pos.entryRKPS, rk)
			outHub = mulDiv(outHub, pos.entryRKPS, rk)
		}
	}
	return outCoin, outHub
}

// RemoveLiquidity is instant and ALWAYS available: it works while the
// exchange or the pool is paused, before or after a ban, and needs no tool.
// Nobody but the position owner can call it for that position.
func RemoveLiquidity(cur realm, coin string, shares uint64, minCoin uint64, minGrin uint64, deadline int64) (uint64, uint64) {
	caller := exchangeCaller(cur)
	requireDeadline(deadline)
	p := getPool(coin)
	key := coin + ":" + caller
	if !lpPositions.Has(key) {
		panic("no liquidity position in " + coin)
	}
	pos := lpPositions.Get(key).(*lpPos)
	if shares == 0 || shares > pos.shares {
		panic("invalid shares")
	}
	outCoin, outHub := lpPayout(p, pos, shares, time.Now().Unix())
	if outCoin < minCoin || outHub < minGrin {
		panic("slippage: output below minimum")
	}
	p.rCoin = subChk(p.rCoin, outCoin)
	p.rHub = subChk(p.rHub, outHub)
	p.shares = subChk(p.shares, shares)
	pos.shares = subChk(pos.shares, shares)
	if pos.shares == 0 {
		lpPositions.Remove(key)
	}
	creditBal(caller, coin, outCoin)
	creditBal(caller, hubCoin, outHub)
	chain.Emit("LiquidityRemoved", "coin", coin, "who", caller,
		"coinOut", u(outCoin), "grinOut", u(outHub), "shares", u(shares))
	return outCoin, outHub
}

// poolQuote returns (out, protoFee) for amountIn of the input side; no writes.
func poolQuote(p *pool, inIsHub bool, amountIn uint64) (uint64, uint64) {
	rIn, rOut := p.rCoin, p.rHub
	if inIsHub {
		rIn, rOut = p.rHub, p.rCoin
	}
	fee := mulDivUp(amountIn, poolFeeBps, 10000)
	proto := mulDiv(amountIn, protoFeeBps, 10000)
	if fee >= amountIn {
		return 0, 0
	}
	eff := amountIn - fee
	out := mulDiv(rOut, eff, addChk(rIn, eff)) // floor: pool's favor
	return out, proto
}

func poolOpenForSwaps(p *pool) bool {
	return !p.paused && p.rHub >= minOpenDepthGrin && p.rCoin > 0
}

// poolSwap executes one hop (coin↔grin) for `caller`, crediting nothing to
// the caller: it returns the output so routes can chain hops. The caller's
// input must already have been debited.
func poolSwap(p *pool, inIsHub bool, amountIn uint64) uint64 {
	if !poolOpenForSwaps(p) {
		panic("pool " + p.coin + " is not open for swaps (paused or under 2000 grin depth)")
	}
	out, proto := poolQuote(p, inIsHub, amountIn)
	if out == 0 {
		panic("swap too small")
	}
	kBefore := isqrt128(p.rCoin, p.rHub)
	inNet := subChk(amountIn, proto)
	if inIsHub {
		p.rHub = addChk(p.rHub, inNet)
		p.rCoin = subChk(p.rCoin, out)
		accrueProtocolFee(hubCoin, proto)
	} else {
		p.rCoin = addChk(p.rCoin, inNet)
		p.rHub = subChk(p.rHub, out)
		accrueProtocolFee(p.coin, proto)
	}
	if p.rCoin == 0 || p.rHub == 0 {
		panic("swap would empty the pool")
	}
	// Defense in depth: the invariant must hold after every swap.
	if isqrt128(p.rCoin, p.rHub) < kBefore {
		panic("invariant: k decreased")
	}
	return out
}

// SwapExactIn swaps amountIn of coinIn for at least minOut of coinOut through
// one pool (one side must be grin). For X→Y via grin use SwapRoute.
func SwapExactIn(cur realm, coinIn string, coinOut string, amountIn uint64, minOut uint64, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("amountIn", amountIn)
	requireCoin(coinIn)
	requireCoin(coinOut)
	var p *pool
	inIsHub := coinIn == hubCoin
	if inIsHub && coinOut != hubCoin {
		p = getPool(coinOut)
	} else if !inIsHub && coinOut == hubCoin {
		p = getPool(coinIn)
	} else {
		panic("one side must be grin (use SwapRoute for coin→coin)")
	}
	if !poolOpenForSwaps(p) {
		panic("pool " + p.coin + " is not open for swaps (paused or under 2000 grin depth)")
	}
	if q, _ := poolQuote(p, inIsHub, amountIn); q == 0 || q < minOut {
		panic("slippage: output below minimum")
	}
	requireBalance(caller, coinIn, amountIn)
	// ── all checks passed; writes start here ──
	debitBal(caller, coinIn, amountIn)
	out := poolSwap(p, inIsHub, amountIn)
	creditBal(caller, coinOut, out)
	chain.Emit("Swap", "pool", p.coin, "who", caller, "in", coinIn, "out", coinOut,
		"amountIn", u(amountIn), "amountOut", u(out))
	return out
}

// ── views ────────────────────────────────────────────────────────────────────

func poolJSON(p *pool) string {
	return `{"coin":` + jsonStr(p.coin) + `,"rCoin":"` + u(p.rCoin) + `","rGrin":"` + u(p.rHub) +
		`","shares":"` + u(p.shares) + `","paused":` + strconv.FormatBool(p.paused) +
		`,"open":` + strconv.FormatBool(poolOpenForSwaps(p)) + `}`
}

func PoolInfo(coin string) string {
	if !pools.Has(coin) {
		return `{"coin":` + jsonStr(coin) + `,"exists":false}`
	}
	return poolJSON(getPool(coin))
}

// Pools lists pools in coin order (paginated, ≤ 50 per call).
func Pools(limit int, offset int) string {
	if limit <= 0 || limit > maxViewLimit {
		limit = maxViewLimit
	}
	if offset < 0 {
		offset = 0
	}
	out := "["
	n := 0
	pools.IterateByOffset(offset, limit, func(_ string, v any) bool {
		if n > 0 {
			out += ","
		}
		out += poolJSON(v.(*pool))
		n++
		return false
	})
	return out + "]"
}

// QuoteSwap quotes a single-pool swap; "0" if the pool can't take it.
func QuoteSwap(coinIn string, coinOut string, amountIn uint64) string {
	if amountIn == 0 || amountIn > maxAmount {
		return "0"
	}
	c, inIsHub := coinIn, false
	if coinIn == hubCoin {
		c, inIsHub = coinOut, true
	} else if coinOut != hubCoin {
		return "0"
	}
	if !pools.Has(c) {
		return "0"
	}
	p := getPool(c)
	if !poolOpenForSwaps(p) {
		return "0"
	}
	out, _ := poolQuote(p, inIsHub, amountIn)
	return u(out)
}

// LpPosition shows one position and what it would withdraw right now.
func LpPosition(coin string, addr string) string {
	key := coin + ":" + addr
	if !lpPositions.Has(key) || !pools.Has(coin) {
		return `{"coin":` + jsonStr(coin) + `,"shares":"0"}`
	}
	pos := lpPositions.Get(key).(*lpPos)
	p := getPool(coin)
	now := time.Now().Unix()
	oc, oh := lpPayout(p, pos, pos.shares, now)
	warm := pos.depositTs + warmupSecs - now
	if warm < 0 {
		warm = 0
	}
	return `{"coin":` + jsonStr(coin) + `,"shares":"` + u(pos.shares) + `","poolShares":"` + u(p.shares) +
		`","coinOut":"` + u(oc) + `","grinOut":"` + u(oh) + `","warmupLeft":` + strconv.FormatInt(warm, 10) + `}`
}

// LpPositions lists an address's positions (bounded: at most one per pool,
// paginated by pool order, ≤ 50 pools scanned per call).
func LpPositions(addr string, limit int, offset int) string {
	if limit <= 0 || limit > maxViewLimit {
		limit = maxViewLimit
	}
	if offset < 0 {
		offset = 0
	}
	out := "["
	n := 0
	pools.IterateByOffset(offset, limit, func(coin string, _ any) bool {
		if lpPositions.Has(coin + ":" + addr) {
			if n > 0 {
				out += ","
			}
			out += LpPosition(coin, addr)
			n++
		}
		return false
	})
	return out + "]"
}

package game31

// ── P2P exchange: router (book first while it beats the pool, rest via pools)

import (
	"strconv"
	"time"

	"chain"
)

// poolPathOut quotes amountIn of coinIn → coinOut through the grin pools
// (one hop if either side is grin, else coinIn→grin→coinOut). ok=false if a
// needed pool is missing or not open. Read-only.
func poolPathOut(coinIn, coinOut string, amountIn uint64) (uint64, bool) {
	if amountIn == 0 || coinIn == coinOut {
		return 0, false
	}
	if coinIn == hubCoin || coinOut == hubCoin {
		c, inIsHub := coinIn, false
		if coinIn == hubCoin {
			c, inIsHub = coinOut, true
		}
		if !pools.Has(c) {
			return 0, false
		}
		p := getPool(c)
		if !poolOpenForSwaps(p) {
			return 0, false
		}
		out, _ := poolQuote(p, inIsHub, amountIn)
		return out, out > 0
	}
	mid, ok := poolPathOut(coinIn, hubCoin, amountIn)
	if !ok {
		return 0, false
	}
	return poolPathOut(hubCoin, coinOut, mid)
}

// routePlan splits amountIn between book fills (direct pair) and the pool
// path. A book fill is taken while its rate is at least the pool path's
// average rate for the whole remainder; everything else goes to the pools.
func routePlan(caller, coinIn, coinOut string, amountIn uint64, maxFills int, now int64) ([]fillStep, []*order, uint64, uint64, uint64) {
	steps, expired, _, _ := planFills(caller, coinIn, coinOut, amountIn, maxFills, now)
	var take []fillStep
	remaining := amountIn
	bookOut := uint64(0)
	for _, st := range steps {
		cost := addChk(st.x, mulDivUp(st.x, takerFeeBps, 10000))
		if cost > remaining {
			break
		}
		if pOut, ok := poolPathOut(coinIn, coinOut, remaining); ok {
			// book rate g/cost vs pool average rate pOut/remaining (128-bit compare)
			if mulLess(st.g, remaining, pOut, cost) {
				break
			}
		}
		take = append(take, st)
		remaining = subChk(remaining, cost)
		bookOut = addChk(bookOut, st.g)
	}
	poolOut := uint64(0)
	if remaining > 0 {
		if out, ok := poolPathOut(coinIn, coinOut, remaining); ok {
			poolOut = out
		} else {
			remaining = 0 // no pool path: only the book part executes
		}
	}
	return take, expired, remaining, bookOut, poolOut
}

// SwapRoute swaps up to amountIn of coinIn for at least minOut of coinOut,
// using the order book (direct pair) while it beats the pools and the grin
// pools for the rest. Coins not needed are never debited.
func SwapRoute(cur realm, coinIn string, coinOut string, amountIn uint64, minOut uint64, maxFills int, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("amountIn", amountIn)
	requireCoin(coinIn)
	requireCoin(coinOut)
	if coinIn == coinOut {
		panic("coinIn and coinOut must differ")
	}
	take, expired, poolIn, bookOut, poolOut := routePlan(caller, coinIn, coinOut, amountIn, maxFills, time.Now().Unix())
	planned := addChk(bookOut, poolOut)
	if planned == 0 || planned < minOut {
		panic("slippage: output below minimum")
	}
	need := poolIn
	for _, st := range take {
		need = addChk(need, addChk(st.x, mulDivUp(st.x, takerFeeBps, 10000)))
	}
	requireBalance(caller, coinIn, need)
	// ── all checks passed; writes start here ──
	for _, o := range expired {
		closeOrder(o, "expired")
	}
	out := executeFills(caller, coinIn, take)
	if poolIn > 0 {
		debitBal(caller, coinIn, poolIn)
		if coinIn == hubCoin {
			out = addChk(out, poolSwap(getPool(coinOut), true, poolIn))
		} else if coinOut == hubCoin {
			out = addChk(out, poolSwap(getPool(coinIn), false, poolIn))
		} else {
			mid := poolSwap(getPool(coinIn), false, poolIn)
			out = addChk(out, poolSwap(getPool(coinOut), true, mid))
		}
	}
	if out != planned {
		panic("invariant: route plan mismatch")
	}
	creditBal(caller, coinOut, out)
	chain.Emit("SwapRouted", "who", caller, "in", coinIn, "out", coinOut, "amountIn", u(amountIn),
		"bookFills", strconv.Itoa(len(take)), "poolIn", u(poolIn), "amountOut", u(out))
	return out
}

// QuoteRoute previews SwapRoute: how much goes to the book vs the pools and
// the expected output (fees included).
func QuoteRoute(caller string, coinIn string, coinOut string, amountIn uint64, maxFills int) string {
	if amountIn == 0 || amountIn > maxAmount || coinIn == coinOut {
		return `{"out":"0"}`
	}
	if _, ok := coinRarity[coinIn]; !ok {
		return `{"out":"0"}`
	}
	if _, ok := coinRarity[coinOut]; !ok {
		return `{"out":"0"}`
	}
	take, _, poolIn, bookOut, poolOut := routePlan(caller, coinIn, coinOut, amountIn, maxFills, time.Now().Unix())
	bookIn := uint64(0)
	for _, st := range take {
		bookIn = addChk(bookIn, addChk(st.x, mulDivUp(st.x, takerFeeBps, 10000)))
	}
	return `{"bookIn":"` + u(bookIn) + `","bookOut":"` + u(bookOut) + `","bookFills":` + strconv.Itoa(len(take)) +
		`,"poolIn":"` + u(poolIn) + `","poolOut":"` + u(poolOut) + `","out":"` + u(addChk(bookOut, poolOut)) +
		`","unused":"` + u(amountIn-bookIn-poolIn) + `"}`
}

package game31

// Exchange unit, attack and invariant tests. See docs/EXCHANGE_SECURITY_REVIEW.md
// for the threat → code → test map.
//
// gno test caveat: revive() catches a panic but does NOT roll back realm
// state. The exchange validates everything before its first write, so a
// failing call must leave state untouched — several tests assert exactly that
// (snapshot before, compare after).

import (
	"chain"
	"strconv"
	"strings"
	"testing"
	"time"
)

// ── helpers ──────────────────────────────────────────────────────────────────

// exOpen finalizes the migration and unpauses for one test; the returned
// func restores the previous global state (other test files depend on it).
func exOpen() func() {
	setup()
	wasFinal, wasPaused, wasGame := migrationFinalized, exPaused, paused
	migrationFinalized, exPaused, paused = true, false, false
	return func() { migrationFinalized, exPaused, paused = wasFinal, wasPaused, wasGame }
}


// trader: owns wood+stone (can trade, receives up to rarity 3).
func trader(name string) address {
	a := ta(name)
	ownedTools.Set(a.String(), "starter-twig,twig,wood,stone")
	return a
}

func dl() int64 { return time.Now().Unix() + 600 }

// panicMsg runs f and returns its panic message ("" if none). For internal
// (non-crossing) helpers, where revive() does not apply.
func panicMsg(f func()) (msg string) {
	defer func() {
		if r := recover(); r != nil {
			msg = errOf(r)
		}
	}()
	f()
	return ""
}

func errOf(r any) string {
	switch v := r.(type) {
	case nil:
		return ""
	case string:
		return v
	case error:
		return v.Error()
	}
	return "?"
}

// coinTotal = every unit of `coin` the realm accounts for: all balances,
// pool reserves, order escrow, admin fees and the casino pool.
func coinTotal(coin string) uint64 {
	tot := uint64(0)
	balances.Iterate("", "", func(k string, v any) bool {
		if strings.HasSuffix(k, ":"+coin) {
			n, _ := strconv.ParseUint(v.(string), 10, 64)
			tot += n
		}
		return false
	})
	pools.Iterate("", "", func(_ string, v any) bool {
		p := v.(*pool)
		if p.coin == coin {
			tot += p.rCoin
		}
		if coin == hubCoin {
			tot += p.rHub
		}
		return false
	})
	forEachOrder(func(o *order) {
		if o.give == coin {
			tot += o.remGive
		}
	})
	return tot + getU(&adminFees, coin) + getU(&casinoPool, coin)
}

func lpSum(coin string) uint64 {
	s := uint64(0)
	lpPositions.Iterate(coin+":", coin+";", func(_ string, v any) bool {
		s += v.(*lpPos).shares
		return false
	})
	return s
}

// stateSig is a cheap fingerprint of everything the exchange owns + balances.
func stateSig(coins ...string) string {
	s := ""
	for _, c := range coins {
		s += c + "=" + u(coinTotal(c)) + ";"
		if pools.Has(c) {
			p := getPool(c)
			s += u(p.rCoin) + "/" + u(p.rHub) + "/" + u(p.shares) + ";"
		}
	}
	return s + "orders=" + u(openOrderTotal) + ";book=" + strconv.Itoa(sideTotal()) + ";next=" + u(nextOrderId)
}

func balSig(addrs []address, coins []string) string {
	s := ""
	for _, a := range addrs {
		for _, c := range coins {
			s += u(bal(a, c)) + ","
		}
	}
	return s
}

// ── gates ────────────────────────────────────────────────────────────────────

func TestEx_Gates(cur realm, t *testing.T) {
	restore := exOpen()
	defer restore()
	// seedPool: the caller must already act as `lp` (testing.SetRealm can't be
	// switched from inside a closure). Pools are created by the admin API in
	// TestEx_Gates; here the empty pool record is written directly.
	seedPool := func(coin string, lp address, coinAmt, grinAmt uint64) uint64 {
		if !pools.Has(coin) {
			pools.Set(coin, &pool{coin: coin})
		}
		give(lp, coin, coinAmt)
		give(lp, "grin", grinAmt)
		return AddLiquidity(cross(cur), coin, coinAmt, grinAmt, 0, dl())
	}
	lp := trader("gate-lp")
	testing.SetRealm(testing.NewUserRealm(lp))
	seedPool("joy", lp, 10000, 10000)

	// trading only after FinalizeMigration
	migrationFinalized = false
	testing.SetRealm(testing.NewUserRealm(lp))
	mustAbort(t, "before finalize", revive(func() { SwapExactIn(cross(cur), "grin", "joy", 10, 0, dl()) }), "FinalizeMigration")
	mustAbort(t, "transfer before finalize", revive(func() { Transfer(cross(cur), "grin", ta("x").String(), "1") }), "FinalizeMigration")
	migrationFinalized = true

	// no tool requirement: a Fist-only account (no tools at all) can trade
	noob := ta("gate-noob")
	give(noob, "grin", 100)
	testing.SetRealm(testing.NewUserRealm(noob))
	if got := SwapExactIn(cross(cur), "grin", "joy", 10, 1, dl()); got == 0 || bal(noob, "joy") != got {
		t.Errorf("fist-only swap: got %d", got)
	}


	// deadlines are mandatory and enforced
	mustAbort(t, "no deadline", revive(func() { SwapExactIn(cross(cur), "grin", "joy", 10, 0, 0) }), "deadline required")
	mustAbort(t, "deadline passed", revive(func() { SwapExactIn(cross(cur), "grin", "joy", 10, 0, time.Now().Unix()-1) }), "deadline passed")

	// realm (code) callers are rejected — no cross-realm surface
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/evil/proxy"))
	mustAbort(t, "realm caller swap", revive(func() { SwapExactIn(cross(cur), "grin", "joy", 10, 0, dl()) }), "directly from a user")
	mustAbort(t, "realm caller remove", revive(func() { RemoveLiquidity(cross(cur), "joy", 1, 0, 0, dl()) }), "directly from a user")

	// fake coins and overflow-sized inputs
	testing.SetRealm(testing.NewUserRealm(lp))
	mustAbort(t, "fake coin", revive(func() { SwapExactIn(cross(cur), "grin", "fake-coin", 10, 0, dl()) }), "unknown coin")
	mustAbort(t, "fake give", revive(func() { PlaceOrder(cross(cur), "fake-coin", 100, "grin", 100, 0) }), "unknown coin")
	mustAbort(t, "huge amount", revive(func() { SwapExactIn(cross(cur), "grin", "joy", maxAmount+1, 0, dl()) }), "between 1 and")
	mustAbort(t, "max uint", revive(func() { PlaceOrder(cross(cur), "grin", ^uint64(0), "joy", 1, 0) }), "between 1 and")
	mustAbort(t, "zero", revive(func() { AddLiquidity(cross(cur), "joy", 0, 10, 0, dl()) }), "between 1 and")
	mustAbort(t, "no pool", revive(func() { SwapExactIn(cross(cur), "grin", "cool", 10, 0, dl()) }), "no pool")
	mustAbort(t, "coin→coin needs route", revive(func() { SwapExactIn(cross(cur), "joy", "cool", 10, 0, dl()) }), "one side must be grin")

	// only the admin creates/pauses pools
	mustAbort(t, "player CreatePool", revive(func() { CreatePool(cross(cur), "cool") }), "admin only")
	mustAbort(t, "player pause", revive(func() { SetExchangePaused(cross(cur), true) }), "admin only")
	mustAbort(t, "player fee withdraw", revive(func() { WithdrawProtocolFees(cross(cur), "grin") }), "admin only")
	testing.SetRealm(testing.NewUserRealm(admin))
	mustAbort(t, "grin pool", revive(func() { CreatePool(cross(cur), "grin") }), "hub coin")
	mustAbort(t, "fake pool", revive(func() { CreatePool(cross(cur), "fake-coin") }), "unknown coin")
	mustAbort(t, "dup pool", revive(func() { CreatePool(cross(cur), "joy") }), "pool exists")
}

// ── pools ────────────────────────────────────────────────────────────────────

func TestEx_PoolLifecycleAndFees(cur realm, t *testing.T) {
	restore := exOpen()
	defer restore()
	// seedPool: the caller must already act as `lp` (testing.SetRealm can't be
	// switched from inside a closure). Pools are created by the admin API in
	// TestEx_Gates; here the empty pool record is written directly.
	seedPool := func(coin string, lp address, coinAmt, grinAmt uint64) uint64 {
		if !pools.Has(coin) {
			pools.Set(coin, &pool{coin: coin})
		}
		give(lp, coin, coinAmt)
		give(lp, "grin", grinAmt)
		return AddLiquidity(cross(cur), coin, coinAmt, grinAmt, 0, dl())
	}
	lp, tr := trader("pl-lp"), trader("pl-tr")
	sig0 := u(coinTotal("cool")) + "/" + u(coinTotal("grin"))

	// first deposit: any ratio (open economy), 1000 shares burned
	testing.SetRealm(testing.NewUserRealm(lp))
	minted := seedPool("cool", lp, 1000, 1500) // √(1.5M)=1224
	p := getPool("cool")
	if minted != 224 || p.shares != 1224 || lpSum("cool")+minLiquidity != p.shares {
		t.Errorf("first deposit minted=%d shares=%d lpSum=%d", minted, p.shares, lpSum("cool"))
	}
	// under 2000 grin depth: no swaps yet
	give(tr, "grin", 100000)
	give(tr, "cool", 100000)
	testing.SetRealm(testing.NewUserRealm(tr))
	mustAbort(t, "filling pool", revive(func() { SwapExactIn(cross(cur), "grin", "cool", 10, 0, dl()) }), "not open for swaps")
	if QuoteSwap("grin", "cool", 10) != "0" {
		t.Errorf("quote on filling pool")
	}
	// later deposit at the pool ratio
	give(lp, "cool", 10000)
	give(lp, "grin", 15000)
	testing.SetRealm(testing.NewUserRealm(lp))
	AddLiquidity(cross(cur), "cool", 10000, 15000, 1, dl())
	if p.rHub < minOpenDepthGrin || lpSum("cool")+minLiquidity != p.shares {
		t.Errorf("after add: %s lpSum=%d", PoolInfo("cool"), lpSum("cool"))
	}

	// swap grin→cool: fee 0.5% (ceil), proto 0.15% (floor) split 50/50
	testing.SetRealm(testing.NewUserRealm(tr))
	q, _ := strconv.ParseUint(QuoteSwap("grin", "cool", 1000), 10, 64)
	k0 := isqrt128(p.rCoin, p.rHub)
	adm0, cas0 := getU(&adminFees, "grin"), getU(&casinoPool, "grin")
	out := SwapExactIn(cross(cur), "grin", "cool", 1000, q, dl())
	if out != q || out == 0 {
		t.Errorf("out=%d quote=%d", out, q)
	}
	if getU(&adminFees, "grin")-adm0 != 0 || getU(&casinoPool, "grin")-cas0 != 1 {
		// proto = floor(1000×15/10000) = 1 → admin floor(0.5)=0, casino 1
		t.Errorf("fee split admin+%d casino+%d", getU(&adminFees, "grin")-adm0, getU(&casinoPool, "grin")-cas0)
	}
	if isqrt128(p.rCoin, p.rHub) < k0 {
		t.Errorf("k decreased")
	}
	// bigger swap the other way: proto 15 → admin 7, casino 8
	adm0, cas0 = getU(&adminFees, "cool"), getU(&casinoPool, "cool")
	SwapExactIn(cross(cur), "cool", "grin", 10000, 1, dl())
	if getU(&adminFees, "cool")-adm0 != 7 || getU(&casinoPool, "cool")-cas0 != 8 {
		t.Errorf("fee split cool admin+%d casino+%d", getU(&adminFees, "cool")-adm0, getU(&casinoPool, "cool")-cas0)
	}

	// slippage revert changes nothing (validate-then-write)
	before := stateSig("cool", "grin") + balSig([]address{tr}, []string{"cool", "grin"})
	mustAbort(t, "minOut", revive(func() { SwapExactIn(cross(cur), "grin", "cool", 1000, 1_000_000, dl()) }), "slippage")
	mustAbort(t, "insufficient", revive(func() { SwapExactIn(cross(cur), "grin", "cool", maxAmount, 0, dl()) }), "insufficient")
	if after := stateSig("cool", "grin") + balSig([]address{tr}, []string{"cool", "grin"}); after != before {
		t.Errorf("failed swap changed state:\n%s\n%s", before, after)
	}

	// LP exits fully after warm-up: gets ≥ deposit in value terms thanks to fees
	testing.SkipHeights(200) // > 600 s
	testing.SetRealm(testing.NewUserRealm(lp))
	pos := lpPositions.Get("cool:" + lp.String()).(*lpPos)
	oc, og := RemoveLiquidity(cross(cur), "cool", pos.shares, 0, 0, dl())
	if lpPositions.Has("cool:"+lp.String()) || p.shares != minLiquidity {
		t.Errorf("position not closed, shares=%d", p.shares)
	}
	if oc == 0 || og == 0 || p.rCoin == 0 || p.rHub == 0 {
		t.Errorf("remove out %d/%d, pool left %d/%d", oc, og, p.rCoin, p.rHub)
	}
	// conservation across the whole test
	_ = sig0
	if lpSum("cool")+minLiquidity != p.shares {
		t.Errorf("lp sum")
	}
}

